int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    string s; long long x, y; cin >> s >> x >> y;
    if (x > y) { reverse(s.begin(), s.end()); swap(x, y); }
    // With x <= y some optimum sets the wildcards to 0...0 1...1: start all 1, flip left to right.
    string filled = s;
    for (char &c : filled) if (c == '!') c = '1';
    long long zero = 0, one = 0, cost = 0;
    for (char c : filled) {
        if (c == '0') { cost += one * y; zero++; }
        else { cost += zero * x; one++; }
    }
    long long right0 = zero, right1 = one, left0 = 0, left1 = 0, best = cost;
    for (size_t i = 0; i < s.size(); i++) {
        char c = filled[i];
        if (c == '0') right0--; else right1--;
        if (s[i] == '!') {
            cost += left1 * y - left0 * x + right1 * x - right0 * y;
            c = '0';
            best = min(best, cost);
        }
        if (c == '0') left0++; else left1++;
    }
    cout << best % 1000000007LL << "\n";
}

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        char[] s = r.next().toCharArray();
        long x = r.nextLong(), y = r.nextLong();
        int n = s.length;
        if (x > y) {
            for (int i = 0, j = n - 1; i < j; i++, j--) { char t = s[i]; s[i] = s[j]; s[j] = t; }
            long t = x; x = y; y = t;
        }
        // With x <= y some optimum sets the wildcards to 0...0 1...1: start all 1, flip left to right.
        long zero = 0, one = 0, cost = 0;
        for (char c : s) {
            if (c == '0') { cost += one * y; zero++; }
            else { cost += zero * x; one++; }
        }
        long right0 = zero, right1 = one, left0 = 0, left1 = 0, best = cost;
        for (char orig : s) {
            boolean isZero = orig == '0';
            if (isZero) right0--; else right1--;
            if (orig == '!') {
                cost += left1 * y - left0 * x + right1 * x - right0 * y;
                isZero = true;
                best = Math.min(best, cost);
            }
            if (isZero) left0++; else left1++;
        }
        System.out.println(best % 1_000_000_007L);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	s := []byte(readToken())
	x, y := readInt(), readInt()
	n := len(s)
	if x > y {
		for i, j := 0, n-1; i < j; i, j = i+1, j-1 {
			s[i], s[j] = s[j], s[i]
		}
		x, y = y, x
	}
	// With x <= y some optimum sets the wildcards to 0...0 1...1: start all 1, flip left to right.
	zero, one, cost := 0, 0, 0
	for _, c := range s {
		if c == '0' {
			cost += one * y
			zero++
		} else {
			cost += zero * x
			one++
		}
	}
	right0, right1, left0, left1, best := zero, one, 0, 0, cost
	for _, orig := range s {
		isZero := orig == '0'
		if isZero {
			right0--
		} else {
			right1--
		}
		if orig == '!' {
			cost += left1*y - left0*x + right1*x - right0*y
			isZero = true
			best = min(best, cost)
		}
		if isZero {
			left0++
		} else {
			left1++
		}
	}
	fmt.Println(best % 1000000007)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
